package com.esn.smp.gameplay;
import com.esn.smp.data.ESNDataStore;
import org.bukkit.*;import org.bukkit.attribute.Attribute;import org.bukkit.command.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;import org.bukkit.event.inventory.InventoryClickEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.persistence.*;import org.bukkit.plugin.java.JavaPlugin;import java.io.*;import java.sql.*;import java.util.*;import java.util.concurrent.ThreadLocalRandom;
public final class RPGOverhaul implements Listener,CommandExecutor,AutoCloseable{
 private static final String SKILL_MENU=ChatColor.DARK_AQUA+"ESN Skill Tree",SEASON_MENU=ChatColor.LIGHT_PURPLE+"ESN Season Pass";private final Map<UUID,Integer> seasonPage=new HashMap<>();
 private final JavaPlugin p;private final ESNDataStore eco;private Connection db;private final NamespacedKey evolve,ability,seasonMagic;private final Map<UUID,Map<UUID,Double>> damage=new HashMap<>();private final Map<UUID,Long> cooldown=new HashMap<>();private String rotation="Titan Hunt";
 public RPGOverhaul(JavaPlugin p,ESNDataStore eco)throws Exception{this.p=p;this.eco=eco;evolve=new NamespacedKey(p,"evolution");ability=new NamespacedKey(p,"ability");seasonMagic=new NamespacedKey(p,"season_magic");db=DriverManager.getConnection("jdbc:sqlite:"+new File(p.getDataFolder(),"rpg-overhaul.db"));try(Statement s=db.createStatement()){s.execute("CREATE TABLE IF NOT EXISTS rpg(uuid TEXT PRIMARY KEY,bosses INTEGER DEFAULT 0,dungeons INTEGER DEFAULT 0,raids INTEGER DEFAULT 0,contracts INTEGER DEFAULT 0,skillpoints INTEGER DEFAULT 0,seasonxp INTEGER DEFAULT 0,treasures INTEGER DEFAULT 0,fish INTEGER DEFAULT 0)");s.execute("CREATE TABLE IF NOT EXISTS codex(uuid TEXT,boss TEXT,kills INTEGER DEFAULT 0,PRIMARY KEY(uuid,boss))");s.execute("CREATE TABLE IF NOT EXISTS skills(uuid TEXT,skill TEXT,level INTEGER DEFAULT 0,PRIMARY KEY(uuid,skill))");s.execute("CREATE TABLE IF NOT EXISTS contracts(uuid TEXT PRIMARY KEY,boss INTEGER DEFAULT 0,dungeon INTEGER DEFAULT 0,treasure INTEGER DEFAULT 0,claimed INTEGER DEFAULT 0)");s.execute("CREATE TABLE IF NOT EXISTS season_claims(uuid TEXT,tier INTEGER,PRIMARY KEY(uuid,tier))");}Bukkit.getScheduler().runTaskTimer(p,this::rotate,1200L,72000L);Bukkit.getScheduler().runTaskTimer(p,this::cleanupMemory,1200L,1200L);Bukkit.getScheduler().runTaskLater(p,()->Bukkit.getOnlinePlayers().forEach(this::grantOwnerSeasonPass),20L);}
 private Location safeOwnerLocation(Player x){Location base=x.getLocation().clone();World w=base.getWorld();if(w==null)return base;for(int dy=0;dy<=12;dy++){Location q=base.clone().add(0,dy,0);if(q.getBlock().isPassable()&&q.clone().add(0,1,0).getBlock().isPassable()&&q.clone().add(0,-1,0).getBlock().getType().isSolid())return q.getBlock().getLocation().add(.5,0,.5);}Location spawn=w.getSpawnLocation().clone();int y=Math.max(spawn.getBlockY(),w.getHighestBlockYAt(spawn.getBlockX(),spawn.getBlockZ())+1);Location q=new Location(w,spawn.getBlockX()+.5,y,spawn.getBlockZ()+.5,spawn.getYaw(),spawn.getPitch());for(int dy=0;dy<4;dy++){q.clone().add(0,dy,0).getBlock().setType(Material.AIR,false);}return q;}
 private void ensureOwnerSafe(Player x){if(!x.hasPermission("esnsmp.owner"))return;Location here=x.getLocation();if(!here.getBlock().isPassable()||!here.clone().add(0,1,0).getBlock().isPassable()){Location safe=safeOwnerLocation(x);x.teleport(safe);x.setFallDistance(0);x.setFireTicks(0);x.sendMessage(ChatColor.YELLOW+"Owner safety moved you out of an unsafe spawn location.");}}
 private void recoverOwnerSeasonPass(Player x){if(!x.hasPermission("esnsmp.owner")){x.sendMessage(ChatColor.RED+"Owner only.");return;}ensureOwnerSafe(x);int delivered=0;for(int tier=1;tier<=100;tier++){ItemStack reward=seasonReward(tier);Map<Integer,ItemStack> left=x.getInventory().addItem(reward);left.values().forEach(z->x.getWorld().dropItemNaturally(x.getLocation(),z));delivered++;}x.sendMessage(ChatColor.GOLD+""+ChatColor.BOLD+"Recovered all "+delivered+" Season Pass item rewards. Coins were not duplicated.");}
 private void grantOwnerSeasonPass(Player x){if(!x.hasPermission("esnsmp.owner"))return;ensureOwnerSafe(x);try{ensure(x);try(PreparedStatement q=db.prepareStatement("UPDATE rpg SET seasonxp=MAX(seasonxp,24750) WHERE uuid=?")){q.setString(1,x.getUniqueId().toString());q.executeUpdate();}int granted=0;for(int tier=1;tier<=100;tier++){if(seasonClaimed(x,tier))continue;try(PreparedStatement q=db.prepareStatement("INSERT OR IGNORE INTO season_claims(uuid,tier) VALUES(?,?)")){q.setString(1,x.getUniqueId().toString());q.setInt(2,tier);q.executeUpdate();}long coins=seasonCoins(tier);if(coins>0)eco.deposit(x,coins);ItemStack reward=seasonReward(tier);Map<Integer,ItemStack> left=x.getInventory().addItem(reward);left.values().forEach(z->x.getWorld().dropItemNaturally(x.getLocation(),z));granted++;}if(granted>0)x.sendMessage(ChatColor.GOLD+""+ChatColor.BOLD+"OWNER Season Pass unlocked: Tier 100 + all "+granted+" unclaimed rewards delivered.");}catch(Exception ex){p.getLogger().warning("Owner Season Pass grant failed for "+x.getName()+": "+ex.getMessage());}}
 @EventHandler public void ownerSeasonJoin(PlayerJoinEvent e){if(e.getPlayer().hasPermission("esnsmp.owner"))ensureOwnerSafe(e.getPlayer());Bukkit.getScheduler().runTaskLater(p,()->{ensureOwnerSafe(e.getPlayer());grantOwnerSeasonPass(e.getPlayer());},10L);}
 private void ensure(Player x)throws Exception{try(PreparedStatement q=db.prepareStatement("INSERT OR IGNORE INTO rpg(uuid) VALUES(?)")){q.setString(1,x.getUniqueId().toString());q.executeUpdate();}}
 private int get(Player x,String c)throws Exception{ensure(x);try(PreparedStatement q=db.prepareStatement("SELECT "+c+" FROM rpg WHERE uuid=?")){q.setString(1,x.getUniqueId().toString());try(ResultSet r=q.executeQuery()){return r.next()?r.getInt(1):0;}}}
 private void add(Player x,String c,int n){try{ensure(x);try(PreparedStatement q=db.prepareStatement("UPDATE rpg SET "+c+"="+c+"+? WHERE uuid=?")){q.setInt(1,n);q.setString(2,x.getUniqueId().toString());q.executeUpdate();}}catch(Exception ex){p.getLogger().warning("RPG progress: "+ex.getMessage());}}
 public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(!(s instanceof Player x))return true;try{switch(c.getName()){case"bosscodex"->codex(x);case"skilltree"->{if(a.length>=2&&a[0].equalsIgnoreCase("spend"))spendSkill(x,a[1]);else openSkills(x);}case"contracts2"->contracts(x);case"gearupgrade"->upgrade(x);case"seasonpass"->{if(a.length>0&&a[0].equalsIgnoreCase("recover"))recoverOwnerSeasonPass(x);else openSeason(x);}case"rpgprofile"->x.sendMessage(ChatColor.AQUA+x.getName()+" | Bosses "+get(x,"bosses")+" | Skill Points "+get(x,"skillpoints")+" | Treasure "+get(x,"treasures")+" | Fishing "+get(x,"fish"));case"rotation"->x.sendMessage(ChatColor.GOLD+"Current weekly focus: "+rotation);case"bossdiag"->diag(x);case"bosssummon"->summon(x);}}catch(Exception ex){x.sendMessage(ChatColor.RED+"RPG system unavailable; check console.");p.getLogger().warning("RPG command: "+ex.getMessage());}return true;}

 private ItemStack menuItem(Material m,String n,String... lore){ItemStack i=new ItemStack(m);ItemMeta im=i.getItemMeta();im.setDisplayName(n);im.setLore(Arrays.asList(lore));i.setItemMeta(im);return i;}
 private void openSkills(Player x)throws Exception{Inventory v=Bukkit.createInventory(null,54,SKILL_MENU);v.setItem(4,menuItem(Material.NETHER_STAR,ChatColor.GOLD+"Available Skill Points: "+get(x,"skillpoints"),ChatColor.GRAY+"Bosses award skill points.",ChatColor.YELLOW+"Click a skill below to spend 1 point."));String[] names={"combat","mining","farming","fishing","magic","runes","exploration"};Material[] mats={Material.NETHERITE_SWORD,Material.DIAMOND_PICKAXE,Material.WHEAT,Material.FISHING_ROD,Material.BLAZE_POWDER,Material.ENCHANTING_TABLE,Material.COMPASS};int[] slots={10,11,12,13,14,15,16};for(int j=0;j<names.length;j++){int lv=skill(x,names[j]);v.setItem(slots[j],menuItem(mats[j],ChatColor.AQUA+names[j].toUpperCase(Locale.ROOT),ChatColor.GRAY+"Level: "+lv+"/25",ChatColor.GREEN+"Click to spend 1 Skill Point"));}v.setItem(45,menuItem(Material.ARROW,ChatColor.YELLOW+"Server Menu",ChatColor.GRAY+"Back to /menu"));v.setItem(49,menuItem(Material.BARRIER,ChatColor.RED+"Close"));v.setItem(53,menuItem(Material.TOTEM_OF_UNDYING,ChatColor.LIGHT_PURPLE+"Season Pass",ChatColor.GRAY+"Open Season progression"));x.openInventory(v);}
 private boolean seasonClaimed(Player x,int tier)throws Exception{try(PreparedStatement q=db.prepareStatement("SELECT 1 FROM season_claims WHERE uuid=? AND tier=?")){q.setString(1,x.getUniqueId().toString());q.setInt(2,tier);try(ResultSet rs=q.executeQuery()){return rs.next();}}}
 private int seasonLevel(Player x)throws Exception{return Math.min(100,get(x,"seasonxp")/250+1);}
 private ItemStack angelWings(){ItemStack i=new ItemStack(Material.ELYTRA);ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.WHITE+""+ChatColor.BOLD+"✦ ANGEL WINGS ✦");m.setLore(List.of(ChatColor.AQUA+"Season Pass Reward I",ChatColor.GRAY+"A celestial relic from ESN.",ChatColor.GOLD+"Unbreaking CC"));i.setItemMeta(m);i.addUnsafeEnchantment(org.bukkit.enchantments.Enchantment.UNBREAKING,200);return i;}
 private ItemStack magicItem(Material mat,String name,String id,String lore){ItemStack i=new ItemStack(mat);ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.LIGHT_PURPLE+""+ChatColor.BOLD+name);m.setLore(List.of(ChatColor.AQUA+lore,ChatColor.GRAY+"Right-click to unleash its magic."));m.getPersistentDataContainer().set(seasonMagic,PersistentDataType.STRING,id);i.setItemMeta(m);i.addUnsafeEnchantment(org.bukkit.enchantments.Enchantment.UNBREAKING,10);return i;}
 private ItemStack seasonReward(int tier){if(tier==1)return angelWings();if(tier==25)return magicItem(Material.BLAZE_ROD,"Inferno Scepter","inferno","Launches a burning blast.");if(tier==40)return magicItem(Material.AMETHYST_SHARD,"Storm Crystal","storm","Calls lightning where you aim.");if(tier==60)return magicItem(Material.HEART_OF_THE_SEA,"Tideheart","tide","Heals and empowers you.");if(tier==75)return magicItem(Material.ECHO_SHARD,"Void Relic","void","Blink through space.");if(tier==90)return magicItem(Material.NETHER_STAR,"Celestial Star","celestial","Unleashes celestial power.");if(tier%10==0)return MegaCrates.key(Math.min(99,tier-1));Material[] mats={Material.DIAMOND,Material.GOLDEN_APPLE,Material.EXPERIENCE_BOTTLE,Material.EMERALD,Material.NETHERITE_SCRAP,Material.ENDER_PEARL,Material.TOTEM_OF_UNDYING,Material.ENCHANTED_GOLDEN_APPLE};ItemStack i=new ItemStack(mats[(tier-2)%mats.length],Math.min(16,1+tier/12));ItemMeta m=i.getItemMeta();m.setDisplayName(ChatColor.LIGHT_PURPLE+"Season Reward "+tier);m.setLore(List.of(ChatColor.GRAY+"Tier "+tier+" item reward"));i.setItemMeta(m);return i;}
 private long seasonCoins(int tier){if(tier==100)return 400000L;if(tier==75)return 200000L;if(tier==50)return 100000L;if(tier==25)return 50000L;return tier%5==0?5000L*tier:0L;}
 private void claimSeason(Player x,int tier)throws Exception{if(tier<1||tier>100)return;if(seasonLevel(x)<tier){x.sendMessage(ChatColor.RED+"Reach Season Tier "+tier+" first.");return;}if(seasonClaimed(x,tier)){x.sendMessage(ChatColor.YELLOW+"You already claimed Tier "+tier+".");return;}db.setAutoCommit(false);try{try(PreparedStatement q=db.prepareStatement("INSERT INTO season_claims(uuid,tier) VALUES(?,?)")){q.setString(1,x.getUniqueId().toString());q.setInt(2,tier);q.executeUpdate();}long coins=seasonCoins(tier);if(coins>0)eco.deposit(x,coins);ItemStack reward=seasonReward(tier);Map<Integer,ItemStack> left=x.getInventory().addItem(reward);left.values().forEach(z->x.getWorld().dropItemNaturally(x.getLocation(),z));db.commit();x.sendMessage(ChatColor.GREEN+"Claimed Season Tier "+tier+(coins>0?" + "+coins+" Coins":"")+"!");}catch(Exception ex){db.rollback();throw ex;}finally{db.setAutoCommit(true);}openSeason(x,seasonPage.getOrDefault(x.getUniqueId(),0));}
 private void openSeason(Player x)throws Exception{openSeason(x,0);}
 private void openSeason(Player x,int page)throws Exception{page=Math.max(0,Math.min(5,page));seasonPage.put(x.getUniqueId(),page);Inventory v=Bukkit.createInventory(null,54,SEASON_MENU);int level=seasonLevel(x),xp=get(x,"seasonxp");v.setItem(4,menuItem(Material.TOTEM_OF_UNDYING,ChatColor.GOLD+"Season Tier "+level+"/100",ChatColor.LIGHT_PURPLE+"Season XP: "+xp,ChatColor.GRAY+"250 XP per tier",ChatColor.AQUA+"100 claimable rewards"));for(int j=0;j<18;j++){int tier=page*18+j+1;if(tier>100)break;boolean claimed=seasonClaimed(x,tier),unlocked=level>=tier;ItemStack reward=seasonReward(tier);ItemMeta m=reward.getItemMeta();List<String> lore=m.hasLore()?new ArrayList<>(m.getLore()):new ArrayList<>();long coins=seasonCoins(tier);if(coins>0)lore.add(ChatColor.GOLD+"+"+coins+" ESN Coins");lore.add(claimed?ChatColor.GREEN+"CLAIMED":unlocked?ChatColor.YELLOW+"CLICK TO CLAIM":ChatColor.RED+"LOCKED — Tier "+tier+" required");m.setLore(lore);m.setDisplayName(ChatColor.LIGHT_PURPLE+"Tier "+tier+" • "+ChatColor.stripColor(m.getDisplayName()));reward.setItemMeta(m);v.setItem(9+j,reward);}if(page>0)v.setItem(45,menuItem(Material.ARROW,ChatColor.YELLOW+"Previous Page"));v.setItem(47,menuItem(Material.ENCHANTING_TABLE,ChatColor.AQUA+"Skill Tree"));v.setItem(49,menuItem(Material.BARRIER,ChatColor.RED+"Close"));if(page<5)v.setItem(53,menuItem(Material.ARROW,ChatColor.YELLOW+"Next Page"));x.openInventory(v);}
 @EventHandler public void menuClick(InventoryClickEvent e){String title=e.getView().getTitle();if(!title.equals(SKILL_MENU)&&!title.equals(SEASON_MENU))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player x))return;int s=e.getRawSlot();try{if(title.equals(SKILL_MENU)){String[] names={"combat","mining","farming","fishing","magic","runes","exploration"};int[] slots={10,11,12,13,14,15,16};for(int j=0;j<slots.length;j++)if(s==slots[j]){spendSkill(x,names[j]);openSkills(x);return;}if(s==53){openSeason(x);return;}}else{int page=seasonPage.getOrDefault(x.getUniqueId(),0);if(s>=9&&s<27){int tier=page*18+(s-9)+1;if(tier<=100)claimSeason(x,tier);return;}if(s==45&&page>0){openSeason(x,page-1);return;}if(s==53&&page<5){openSeason(x,page+1);return;}if(s==47){openSkills(x);return;}}if(s==45&&title.equals(SKILL_MENU)){x.closeInventory();Bukkit.dispatchCommand(x,"menu");}else if(s==49)x.closeInventory();}catch(Exception ex){x.sendMessage(ChatColor.RED+"Menu action unavailable.");}}

 private void codex(Player x)throws Exception{x.sendMessage(ChatColor.DARK_PURPLE+"BOSS CODEX");try(PreparedStatement q=db.prepareStatement("SELECT boss,kills FROM codex WHERE uuid=? ORDER BY kills DESC LIMIT 20")){q.setString(1,x.getUniqueId().toString());try(ResultSet r=q.executeQuery()){boolean any=false;while(r.next()){any=true;x.sendMessage(ChatColor.GRAY+r.getString(1)+" — "+r.getInt(2)+" kills");}if(!any)x.sendMessage(ChatColor.GRAY+"Defeat a boss to begin your codex.");}}}
 private int skill(Player x,String sk)throws Exception{try(PreparedStatement q=db.prepareStatement("SELECT level FROM skills WHERE uuid=? AND skill=?")){q.setString(1,x.getUniqueId().toString());q.setString(2,sk);try(ResultSet r=q.executeQuery()){return r.next()?r.getInt(1):0;}}}
 private void skills(Player x)throws Exception{x.sendMessage(ChatColor.AQUA+"SKILL TREE — "+get(x,"skillpoints")+" points");for(String sk:new String[]{"combat","mining","farming","fishing","magic","runes","exploration"})x.sendMessage(ChatColor.GRAY+sk.toUpperCase(Locale.ROOT)+": "+skill(x,sk)+"/25");x.sendMessage(ChatColor.YELLOW+"/skilltree spend <skill>");}
 private void spendSkill(Player x,String sk)throws Exception{sk=sk.toLowerCase(Locale.ROOT);if(!Set.of("combat","mining","farming","fishing","magic","runes","exploration").contains(sk)){x.sendMessage(ChatColor.RED+"Unknown skill.");return;}int pts=get(x,"skillpoints"),lv=skill(x,sk);if(pts<1||lv>=25){x.sendMessage(ChatColor.RED+"No point available or skill is maxed.");return;}try(PreparedStatement q=db.prepareStatement("INSERT INTO skills(uuid,skill,level) VALUES(?,?,1) ON CONFLICT(uuid,skill) DO UPDATE SET level=level+1")){q.setString(1,x.getUniqueId().toString());q.setString(2,sk);q.executeUpdate();}add(x,"skillpoints",-1);x.sendMessage(ChatColor.GREEN+sk+" increased to "+(lv+1)+"/25.");}
 private void contracts(Player x)throws Exception{ensure(x);try(PreparedStatement q=db.prepareStatement("INSERT OR IGNORE INTO contracts(uuid) VALUES(?)")){q.setString(1,x.getUniqueId().toString());q.executeUpdate();}try(PreparedStatement q=db.prepareStatement("SELECT boss,dungeon,treasure,claimed FROM contracts WHERE uuid=?")){q.setString(1,x.getUniqueId().toString());try(ResultSet r=q.executeQuery()){r.next();int b=r.getInt(1),d=r.getInt(2),t=r.getInt(3),claimed=r.getInt(4);if(b>=5&&d>=3&&t>=2&&claimed==0){eco.deposit(x,10000);add(x,"contracts",1);add(x,"seasonxp",1000);try(PreparedStatement u=db.prepareStatement("UPDATE contracts SET claimed=1 WHERE uuid=?")){u.setString(1,x.getUniqueId().toString());u.executeUpdate();}x.sendMessage(ChatColor.GREEN+"Weekly contract completed: +10,000 Coins +1,000 Season XP.");}else x.sendMessage(ChatColor.GOLD+"Weekly Contract — Bosses "+b+"/5 | Dungeons "+d+"/3 | Treasures "+t+"/2"+(claimed==1?" | CLAIMED":""));}}}
 private void upgrade(Player x){ItemStack i=x.getInventory().getItemInMainHand();if(i==null||i.getType().isAir()||!i.hasItemMeta()){x.sendMessage(ChatColor.RED+"Hold equipment to evolve.");return;}ItemMeta m=i.getItemMeta();int lv=m.getPersistentDataContainer().getOrDefault(evolve,PersistentDataType.INTEGER,0);if(lv>=10){x.sendMessage(ChatColor.GOLD+"Maximum Evolution X.");return;}m.getPersistentDataContainer().set(evolve,PersistentDataType.INTEGER,lv+1);List<String> lore=m.hasLore()?new ArrayList<>(m.getLore()):new ArrayList<>();lore.removeIf(z->ChatColor.stripColor(z).startsWith("Evolution:"));lore.add(ChatColor.GOLD+"Evolution: "+(lv+1)+"/10");m.setLore(lore);i.setItemMeta(m);x.sendMessage(ChatColor.GREEN+"Gear evolved to "+(lv+1)+"/10.");}
 private void summon(Player x){ItemStack hand=x.getInventory().getItemInMainHand();if(hand.getType()!=Material.NETHER_STAR){x.sendMessage(ChatColor.RED+"Boss summoning requires a Nether Star.");return;}hand.setAmount(hand.getAmount()-1);Location l=x.getLocation().clone().add(x.getLocation().getDirection().multiply(6));l.setY(x.getWorld().getHighestBlockYAt(l.getBlockX(),l.getBlockZ())+1);LivingEntity z=(LivingEntity)x.getWorld().spawnEntity(l,EntityType.RAVAGER);z.setCustomName(ChatColor.DARK_RED+"SUMMONED TITAN");z.setCustomNameVisible(true);var a=z.getAttribute(Attribute.MAX_HEALTH);if(a!=null){a.setBaseValue(1000);z.setHealth(1000);}z.addScoreboardTag("esnBiomeBoss");z.addScoreboardTag("esnBiome_SUMMONED");z.setPersistent(true);z.setGlowing(true);Bukkit.broadcastMessage(ChatColor.RED+x.getName()+" summoned a Titan at "+l.getBlockX()+", "+l.getBlockY()+", "+l.getBlockZ());}
 private void diag(Player x){long world=Bukkit.getWorlds().stream().flatMap(w->w.getLivingEntities().stream()).filter(e->e.getScoreboardTags().contains("esnWorldBoss")).count(),regional=Bukkit.getWorlds().stream().flatMap(w->w.getLivingEntities().stream()).filter(e->e.getScoreboardTags().contains("esnBiomeBoss")||e.getScoreboardTags().contains("esnSwampBoss")).count();x.sendMessage(ChatColor.GREEN+"Boss diagnostics: world="+world+" regional="+regional+" | Realm crates="+MegaCrates.COUNT+" | DB="+(db!=null));}
 @EventHandler public void hit(EntityDamageByEntityEvent e){if(!(e.getEntity() instanceof LivingEntity b)||!boss(b))return;Player x=e.getDamager() instanceof Player q?q:e.getDamager() instanceof Projectile pr&&pr.getShooter() instanceof Player q?q:null;if(x!=null)damage.computeIfAbsent(b.getUniqueId(),k->new HashMap<>()).merge(x.getUniqueId(),Math.max(0,e.getFinalDamage()),Double::sum);}
 @EventHandler(priority=EventPriority.MONITOR) public void death(EntityDeathEvent e){LivingEntity b=e.getEntity();if(!boss(b))return;Player k=b.getKiller();if(k!=null){add(k,"bosses",1);contract(k,"boss");add(k,"skillpoints",2);add(k,"seasonxp",750);String n=ChatColor.stripColor(b.getCustomName()==null?b.getType().name():b.getCustomName());try(PreparedStatement q=db.prepareStatement("INSERT INTO codex(uuid,boss,kills) VALUES(?,?,1) ON CONFLICT(uuid,boss) DO UPDATE SET kills=kills+1")){q.setString(1,k.getUniqueId().toString());q.setString(2,n);q.executeUpdate();}catch(Exception ignored){}}Map<UUID,Double>d=damage.remove(b.getUniqueId());if(d!=null&&!d.isEmpty()){double total=d.values().stream().mapToDouble(Double::doubleValue).sum();d.entrySet().stream().sorted(Map.Entry.<UUID,Double>comparingByValue().reversed()).limit(3).forEach(z->{Player x=Bukkit.getPlayer(z.getKey());if(x!=null&&z.getValue()>=total*.05){x.giveExp(100);x.sendMessage(ChatColor.GOLD+"Boss participation: "+Math.round(z.getValue())+" damage ("+Math.round(z.getValue()/Math.max(1,total)*100)+"%)");}});}}
 private boolean boss(LivingEntity b){Set<String>t=b.getScoreboardTags();return t.contains("esnWorldBoss")||t.contains("esnSwampBoss")||t.contains("esnBiomeBoss");}
 @EventHandler public void use(PlayerInteractEvent e){ItemStack i=e.getItem();if(i==null||!i.hasItemMeta())return;String magic=i.getItemMeta().getPersistentDataContainer().get(seasonMagic,PersistentDataType.STRING);if(magic!=null){Player x=e.getPlayer();long now=System.currentTimeMillis();long key=x.getUniqueId().getLeastSignificantBits()^magic.hashCode();UUID cd=new UUID(0,key);if(cooldown.getOrDefault(cd,0L)>now){x.sendActionBar(ChatColor.RED+"Season magic is recharging.");return;}cooldown.put(cd,now+15000L);e.setCancelled(true);switch(magic){case"inferno"->{org.bukkit.entity.Fireball f=x.launchProjectile(org.bukkit.entity.Fireball.class);f.setYield(1.5f);f.setIsIncendiary(true);}case"storm"->{org.bukkit.block.Block b=x.getTargetBlockExact(40);Location at=b==null?x.getLocation().add(x.getLocation().getDirection().multiply(8)):b.getLocation();x.getWorld().strikeLightning(at);}case"tide"->{x.setHealth(Math.min(x.getMaxHealth(),x.getHealth()+8));x.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.REGENERATION,org.bukkit.potion.PotionEffect.INFINITE_DURATION,1,true,false,true));}case"void"->{org.bukkit.block.Block b=x.getTargetBlockExact(18);if(b!=null){Location to=b.getLocation().add(.5,1,.5);if(to.getBlock().isPassable()&&to.clone().add(0,1,0).getBlock().isPassable())x.teleport(to);}}case"celestial"->{x.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.STRENGTH,org.bukkit.potion.PotionEffect.INFINITE_DURATION,2,true,false,true));x.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.RESISTANCE,org.bukkit.potion.PotionEffect.INFINITE_DURATION,1,true,false,true));x.getWorld().spawnParticle(Particle.END_ROD,x.getLocation().add(0,1,0),80,2,2,2,.15);}}return;}int lv=i.getItemMeta().getPersistentDataContainer().getOrDefault(evolve,PersistentDataType.INTEGER,0);if(lv<3)return;Player x=e.getPlayer();long now=System.currentTimeMillis();if(cooldown.getOrDefault(x.getUniqueId(),0L)>now)return;cooldown.put(x.getUniqueId(),now+30000);x.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.STRENGTH,100,Math.min(4,lv/2)));x.getWorld().spawnParticle(Particle.ENCHANT,x.getLocation().add(0,1,0),40,1,1,1,.1);x.sendActionBar(ChatColor.GOLD+"Evolution ability activated — 30s cooldown");}
 @EventHandler public void fish(PlayerFishEvent e){if(e.getState()!=PlayerFishEvent.State.CAUGHT_FISH)return;add(e.getPlayer(),"fish",1);if(ThreadLocalRandom.current().nextDouble()<.02){add(e.getPlayer(),"treasures",1);contract(e.getPlayer(),"treasure");e.getPlayer().getInventory().addItem(new ItemStack(Material.HEART_OF_THE_SEA));e.getPlayer().sendMessage(ChatColor.AQUA+"You discovered an ancient fishing treasure!");}}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void seasonMob(org.bukkit.event.entity.EntityDeathEvent e){Player k=e.getEntity().getKiller();if(k!=null&&!boss(e.getEntity()))add(k,"seasonxp",15);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void seasonBreak(org.bukkit.event.block.BlockBreakEvent e){Material m=e.getBlock().getType();if(m.name().contains("ORE"))add(e.getPlayer(),"seasonxp",8);else if(m.name().contains("LOG"))add(e.getPlayer(),"seasonxp",3);}
 @EventHandler public void block(org.bukkit.event.block.BlockBreakEvent e){try{String sk=e.getBlock().getType().name().contains("ORE")?"mining":e.getBlock().getType().name().contains("CROP")?"farming":null;if(sk!=null&&skill(e.getPlayer(),sk)>0&&ThreadLocalRandom.current().nextDouble()<skill(e.getPlayer(),sk)*.01)e.getPlayer().giveExp(2);}catch(Exception ignored){}}
 private void contract(Player x,String type){try{ensure(x);try(PreparedStatement q=db.prepareStatement("INSERT OR IGNORE INTO contracts(uuid) VALUES(?)")){q.setString(1,x.getUniqueId().toString());q.executeUpdate();}String col=type.equals("boss")?"boss":type.equals("treasure")?"treasure":"dungeon";try(PreparedStatement q=db.prepareStatement("UPDATE contracts SET "+col+"="+col+"+1 WHERE uuid=?")){q.setString(1,x.getUniqueId().toString());q.executeUpdate();}}catch(Exception ignored){}}
 private void cleanupMemory(){long now=System.currentTimeMillis();damage.entrySet().removeIf(e->{Entity z=Bukkit.getEntity(e.getKey());return z==null||!z.isValid()||z.isDead();});for(Map<UUID,Double> m:damage.values())m.keySet().removeIf(id->Bukkit.getPlayer(id)==null);cooldown.entrySet().removeIf(e->e.getValue()<=now);seasonPage.keySet().removeIf(id->Bukkit.getPlayer(id)==null);}
 @EventHandler public void ramQuit(PlayerQuitEvent e){UUID id=e.getPlayer().getUniqueId();seasonPage.remove(id);cooldown.remove(id);for(Map<UUID,Double> m:damage.values())m.remove(id);}
 private void rotate(){String[]r={"Titan Hunt","Dungeon Delve","Treasure Rush","Fishing Frenzy","Raid Breaker","Relic Forge"};rotation=r[ThreadLocalRandom.current().nextInt(r.length)];Bukkit.broadcastMessage(ChatColor.LIGHT_PURPLE+"ESN ROTATION: "+rotation+" is now active.");}
 public void close()throws Exception{damage.clear();cooldown.clear();seasonPage.clear();if(db!=null)db.close();}
}